import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 8 The best and the worst","description":"学习 比较级与比较范围，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 8 The best and the worst","description":"学习 比较级与比较范围，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 比较级与比较范围，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 7 Too late","link":"/life/english/new-concept/book-2/unit-01/lesson-007"},"next":{"text":"第二册：实践与进步 · Lesson 9 A cold welcome","link":"/life/english/new-concept/book-2/unit-01/lesson-009"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 7 Too late","link":"/life/english/new-concept/book-2/unit-01/lesson-007"},"next":{"text":"第二册：实践与进步 · Lesson 9 A cold welcome","link":"/life/english/new-concept/book-2/unit-01/lesson-009"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-008.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-008.md"}'),r={name:"life/english/new-concept/book-2/unit-01/lesson-008.md"};function i(l,e,s,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-8-the-best-and-the-worst" tabindex="-1">第二册：实践与进步 · Lesson 8 The best and the worst <a class="header-anchor" href="#第二册-实践与进步-·-lesson-8-the-best-and-the-worst" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 8 The best and the worst&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>邻居们参加小花园评比，整洁、面积和创意并非同一个标准；练习明确比较维度。本课的语言观察是：smaller 比较面积，neater 比较整洁程度；不能因花园小就推断它差。最高级必须放在说明了成员范围的语境中。完成学习后，请比较三个真实或虚构花园，用两个比较级和一个最高级。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>garden</td><td>/ˈɡɑːdən/</td><td>n.</td><td>花园</td><td>a small garden</td></tr><tr><td>prize</td><td>/praɪz/</td><td>n.</td><td>奖品</td><td>win a prize</td></tr><tr><td>neat</td><td>/niːt/</td><td>adj.</td><td>整洁的</td><td>a neat desk</td></tr><tr><td>compare</td><td>/kəmˈpeə/</td><td>v.</td><td>比较</td><td>compare two plans</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>win a prize — 获奖，不能用 earn 表示所有比赛获奖情形</li><li>the best of the three — 三者中最好的，明确比较范围</li></ul><h2 id="语法讲解-比较级与比较范围" tabindex="-1">语法讲解：比较级与比较范围 <a class="header-anchor" href="#语法讲解-比较级与比较范围" aria-label="Permalink to &quot;语法讲解：比较级与比较范围&quot;">​</a></h2><p>比较两者时通常用比较级和 than；在明确的三者或更多成员中选出极值时通常用最高级。短形容词多加 -er/-est，较长形容词多用 more/most，good 与 bad 则是不规则变化。as ... as 中间用原级，否定形式表示不及。比较对象应属于同一类，范围和参照点必须清楚，不能只看到中文“最”就省掉比较范围。本课应用：smaller 比较面积，neater 比较整洁程度；不能因花园小就推断它差。最高级必须放在说明了成员范围的语境中。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Lena&#39;s garden is smaller but neater than mine.</p></blockquote><p>莉娜的花园比我的小，但更整洁。</p><p>smaller 与 neater 是并列比较级；than mine 中 mine 代替 my garden，比较的是花园而非主人。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Her garden is neater than me 比较对象不对称；用 than mine 或 than my garden。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照朗读 smaller、neater、largest，注意最后一个词的 /st/ 不省略。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Lena&#39;s garden is smaller but neater than mine. Omar&#39;s garden is the largest of the three. Lena won the prize for design.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>比较三个真实或虚构花园，用两个比较级和一个最高级。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：smaller 与 neater 是并列比较级；than mine 中 mine 代替 my garden，比较的是花园而非主人。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Her garden is neater than me 比较对象不对称；用 than mine 或 than my garden。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 neat 的比较级：Her garden is ___ than mine.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> neater</p><p><strong>解析：</strong> neat 是单音节形容词，比较级加 -er。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>谁赢得设计奖？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Lena did.</p><p><strong>解析：</strong> 最大的花园属于 Omar，但设计奖属于 Lena。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 good 变成最高级，并写出“三个方案中最好的”。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the best of the three plans</p><p><strong>解析：</strong> good 的最高级是不规则形式 best。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：比较级与比较范围。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-007">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-009">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
